import { ConflictException } from '@nestjs/common';
import { randomBytes } from 'crypto';
import { UsersService } from '../../users/users.service';

export const DEMO_USER = {
  email: 'demo@example.com',
  password: 'Demo-passw0rd',
  name: 'Demo User',
};

export const ADMIN_EMAIL = 'admin@example.com';

export interface SeedResult {
  email: string;
  status: 'created' | 'exists';
  /** Only set when the password was generated by this run. */
  generatedPassword?: string;
}

/** A random password that satisfies the sign-up password policy. */
export function generatePassword(): string {
  return `Aa1-${randomBytes(18).toString('base64url')}`;
}

async function createIfMissing(
  users: UsersService,
  email: string,
  password: string,
  name: string,
): Promise<'created' | 'exists'> {
  try {
    await users.create(email, password, name);
    return 'created';
  } catch (err) {
    if (err instanceof ConflictException) return 'exists';
    throw err;
  }
}

/**
 * Creates the demo user and the admin user if they don't exist yet.
 * Safe to run repeatedly: existing accounts are left untouched.
 *
 * The admin password comes from `adminPassword` (SEED_ADMIN_PASSWORD);
 * when it isn't provided, a random one is generated and returned once.
 */
export async function seedUsers(
  users: UsersService,
  adminPassword?: string,
): Promise<SeedResult[]> {
  const demoStatus = await createIfMissing(
    users,
    DEMO_USER.email,
    DEMO_USER.password,
    DEMO_USER.name,
  );

  const password = adminPassword || generatePassword();
  const adminStatus = await createIfMissing(
    users,
    ADMIN_EMAIL,
    password,
    'Admin',
  );

  return [
    { email: DEMO_USER.email, status: demoStatus },
    {
      email: ADMIN_EMAIL,
      status: adminStatus,
      generatedPassword:
        adminStatus === 'created' && !adminPassword ? password : undefined,
    },
  ];
}
